#Requires -Version 5.1
#Requires -RunAsAdministrator
[CmdletBinding()]param([switch]$LabConfirmed)
. "$PSScriptRoot\CSNetGuideSim-utilities.ps1";Assert-CSNetGuideSafety -LabConfirmed:$LabConfirmed;$p=Initialize-CSNetGuideEnvironment
$conn=@();for($minute=0;$minute-lt60;$minute++){$conn+=[ordered]@{ts=$script:CSNetGuideAnchor.AddMinutes($minute).ToString('o');uid=('SYNTH{0:d4}'-f$minute);id_orig_h='192.0.2.10';id_resp_h='198.51.100.20';id_resp_p=443;proto='tcp';service='ssl';duration=.15;orig_bytes=128+($minute%7);resp_bytes=256+($minute%11);connections=1;synthetic=$true}};Write-CSNetGuideFile(Join-Path $p.Logs 'zeek_conn_synthetic.json')($conn|ConvertTo-Json -Depth 5)'synthetic one-hour beacon log'
Write-CSNetGuideFile(Join-Path $p.Evidence 'rita-like-score.json')(@{input='synthetic generated records; not real Zeek/PCAP';durationMinutes=60;connectionCount=60;regularity='high';jitter='small generated variation';score='training high';RitaExecuted=$false}|ConvertTo-Json)'RITA concept evidence'
$fingerprints=(Get-Content -LiteralPath(Join-Path $PSScriptRoot 'IOC-METADATA.json')-Raw|ConvertFrom-Json).fingerprints;Write-CSNetGuideFile(Join-Path $p.Evidence 'fingerprint-reference.json')($fingerprints|ConvertTo-Json -Depth 6)'JA3/JA3S/JARM reference evidence';Write-CSNetGuideFile(Join-Path $p.Evidence 'arkime-search.json')(@{dataSource='synthetic logs only';queries=@('JA3 known Cobalt values','JA3S paired server values','periodic connections','unusual URI/profile vs infrastructure');ArkimeExecuted=$false;pcapCreated=$false}|ConvertTo-Json)'Arkime concept evidence'
Write-CSNetGuideFile(Join-Path $p.Evidence 'detection-negative-record.json')(@{realZeekLogsRead=0;realPcapsRead=0;RitaExecuted=$false;ArkimeExecuted=$false;JarmScansSent=0;remoteServersScanned=0;networkPacketsGenerated=0;bytesTransferred=0}|ConvertTo-Json)'phase safety record';Add-CSNetGuideTimeline .5 detection 'One-hour synthetic connection series and RITA-style beacon score represented' @{realTraffic=$false;records=60};Add-CSNetGuideTimeline .75 fingerprinting 'JA3/JA3S passive concepts and JARM active-scan caveats represented without probing' @{activeScans=0};Add-CSNetGuideTimeline 1 analysis 'Sigma/Arkime search concepts represented against generated evidence only' @{realPcap=$false}
